}}
{{note2,wide

<div style="display:flex; justify-content:space-between; align-items:baseline; gap:12px; margin-bottom:2px;"><span style="font-family:beaufort-pro; font-size:12.5px; font-weight:900; font-style:italic; white-space:nowrap;">
